settings={'manifest': '', 'manifest_sha256': 'eb064ddfc8d845c60e932ba543625f3e13a39ec32117e7d29db14df8cd22e6ab', 'module_sha256': {'connected_gallery_provenance': '0e552eb81c3a200bda4568b43a7955cef8018ca43d83c4b0172fc903debaa1ec', 'connected_serving_admission': 'c3f608bb98225525629badb07e84567dd198973a7ffa5be161d4f1e600875b0b', 'connected_serving_artifact': '102ab0ab54eff3a0f1d4fa9526966b94f18e648a2a69ad41020148e71741bd08'}, 'modules': {'connected_gallery_provenance': '', 'connected_serving_admission': '', 'connected_serving_artifact': ''}, 'output': '/home/riomus/runs/sfora-connected-serving-artifact-control-179061-v1', 'sources': {'endpoint.pt': '/home/riomus/runs/sfora-connected-mlp-train-control-179061-v1/control-179061-bundle/endpoint.pt', 'gallery-ids.json': '/home/riomus/runs/sfora-connected-gallery-fragment-control-179061-v1/gallery-ids.json', 'gallery-provenance.json': '/home/riomus/runs/sfora-connected-gallery-fragment-control-179061-v1/gallery-provenance.json', 'gallery.bin': '/home/riomus/runs/sfora-connected-gallery-fragment-control-179061-v1/gallery.bin', 'origin-export.json': '/home/riomus/runs/sfora-connected-gallery-fragment-control-179061-v1/origin-export.json', 'origin-owners.json': '/home/riomus/runs/sfora-connected-gallery-fragment-control-179061-v1/origin-owners.json', 'origin.json': '/home/riomus/runs/sfora-connected-gallery-fragment-control-179061-v1/origin.json', 'processor.json': '/home/riomus/runs/sfora-connected-mlp-train-control-179061-v1/control-179061-bundle/processor.json', 'vision.pt': '/home/riomus/runs/sfora-connected-mlp-train-control-179061-v1/control-179061-bundle/vision.pt'}, 'python_sha256': '9258c53dcfde55ba0d0ba9dfdb03bd3f0f30328dc1950f0275f32929fa879b6b'}
import base64, hashlib, importlib.abc, json, os, resource, signal, stat, sys, time, types
from pathlib import Path
resource.setrlimit(resource.RLIMIT_AS,(1073741824,1073741824))
signal.alarm(120)
started=time.monotonic()

def digest(path):
    h=hashlib.sha256()
    with path.open('rb') as stream:
        while block:=stream.read(1024*1024): h.update(block)
    return h.hexdigest()

assert sys.flags.isolated and sys.flags.no_site and sys.dont_write_bytecode
assert Path(sys.executable).resolve()==Path(sys.executable)
assert digest(Path(sys.executable))==settings['python_sha256']
class NoNative(importlib.abc.MetaPathFinder):
    def find_spec(self,fullname,path=None,target=None):
        if fullname.split('.')[0] in {'torch','numpy','PIL','transformers','sfora','cutile_int8'}:
            raise AssertionError('native import forbidden: '+fullname)
sys.meta_path.insert(0,NoNative())
package=types.ModuleType('_assembly_sfora');package.__path__=[]
sys.modules[package.__name__]=package
modules={}
for name in ('connected_gallery_provenance','connected_serving_artifact','connected_serving_admission'):
    raw=base64.b64decode(settings['modules'][name],validate=True)
    assert hashlib.sha256(raw).hexdigest()==settings['module_sha256'][name]
    module=types.ModuleType(package.__name__+'.'+name)
    module.__package__=package.__name__;module.__file__='<pinned assembly '+name+'>'
    sys.modules[module.__name__]=module
    exec(compile(raw,module.__file__,'exec',dont_inherit=True),vars(module))
    modules[name]=module
manifest=base64.b64decode(settings['manifest'],validate=True)
assert hashlib.sha256(manifest).hexdigest()==settings['manifest_sha256']
facts=json.loads(manifest)['files']
output=Path(settings['output'])
assert output.is_absolute() and output.parent.resolve()==output.parent
assert os.statvfs(output.parent).f_bavail*os.statvfs(output.parent).f_frsize>sum(r['bytes'] for r in facts.values())+len(manifest)
output.mkdir(mode=0o700)  # Exclusive new destination; failures leave only diagnostic partial files.

def stamp(info):
    return (info.st_dev,info.st_ino,info.st_mode,info.st_nlink,info.st_size,info.st_mtime_ns,info.st_ctime_ns)

for name,row in sorted(facts.items()):
    source=Path(settings['sources'][name]);assert source.resolve()==source
    fd=os.open(source,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
    try:
        before=os.fstat(fd);assert stat.S_ISREG(before.st_mode) and before.st_nlink==1 and before.st_size==row['bytes']
        h=hashlib.sha256();count=0
        with (output/name).open('xb') as target:
            while block:=os.read(fd,1024*1024):
                assert target.write(block)==len(block)
                h.update(block);count+=len(block)
            target.flush();os.fsync(target.fileno())
        assert h.hexdigest()==row['sha256'] and count==row['bytes']
        assert stamp(before)==stamp(os.fstat(fd))==stamp(source.lstat())
    finally:
        os.close(fd)
with (output/'serving.json').open('xb') as stream:
    assert stream.write(manifest)==len(manifest)
    stream.flush();os.fsync(stream.fileno())
fd=os.open(output,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
try: os.fsync(fd)
finally: os.close(fd)
fragment={name:row['sha256'] for name,row in facts.items() if name not in {'vision.pt','endpoint.pt','processor.json'}}
result=modules['connected_serving_admission'].admit_serving_artifact(str(output),trusted_serving_sha256=settings['manifest_sha256'],trusted_fragment_sha256=fragment)
assert result['manifest']['gallery']['count']==1715 and len(result['files'])==10
assert not any(name.split('.')[0] in {'torch','numpy','PIL','transformers'} for name in sys.modules)
print(json.dumps({'schema':'actual-serving-artifact-filesystem-admission-v1','directory':str(output),'manifest_sha256':settings['manifest_sha256'],'files':result['files'],'source_sha256':settings['module_sha256'],'elapsed_seconds':time.monotonic()-started,'peak_rss_kib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss,'address_space_bytes':1073741824,'filesystem_admission_pass':True,'typed_payload_verified':False,'native_serving_verified':False,'quality_speed_goal_met':False},sort_keys=True))
